&reftitle.description;

 boolis_a
 mixedobject_or_class
 stringclass
 boolallow_string&false;



 Determina se il dato object_or_class è del tipo di oggetto
 class,
 o ha class come uno dei suoi supertipi.

&reftitle.returnvalues;


 Restituisce &true; se object_or_class è del tipo di oggetto
 class,
 o ha class come uno dei suoi supertipi, &false; in caso contrario.

  &reftitle.examples;



    Esempio di is_a


<?php
// definisce una classe
class WidgetFactory
{
  var $oink = 'moo';
}

// crea un nuovo oggetto
$WF = new WidgetFactory();

if (is_a($WF, 'WidgetFactory')) {
  echo "sì, \$WF è ancora una WidgetFactory\n";
}
?>




    Uso dell'operatore instanceof


<?php
// definisce una classe
class WidgetFactory
{
  var $oink = 'moo';
}

// crea un nuovo oggetto
$WF = new WidgetFactory();

if ($WF instanceof WidgetFactory) {
    echo 'Sì, $WF è una WidgetFactory';
}
?>
